// ---------- COVERAGE ----------
function coverage(){const C=ST.contracts,host=$('#cov');let tot=0,ok=0;const rows=[];
  for(const[k,c]of Object.entries(C)){const kk=k.replace('/v3/public/','/v3/');const reg=REG[kk]||{};const req=(c.request||[]).map(f=>'req.'+f);
    let fs=[...req,...[...new Set(Object.values(c.responses).flat())]].map(f=>f.replace(/^\{key\}\.?/,'')).filter(Boolean);fs=[...new Set(fs)];
    const leaf=fs.filter(f=>!fs.some(g=>g!==f&&(g.startsWith(f+'.')||g.startsWith(f+'[]')||g.startsWith(f+'{'))));
    const items=leaf.map(f=>{const hit=reg[f]||reg[f.replace(/^\[\]\./,'')]||reg[f.replace(/^\[\]$/,'')]||(f==='next'?reg['next']:null);tot++;if(hit)ok++;return[f,hit]});
    if(!leaf.length){tot++;const hit=Object.keys(reg).length?Object.values(reg)[0]:null;if(hit)ok++;items.push(['(no body / scalar list)',hit])}
    rows.push([k,items])}
  host.append(h('div',{class:'w'},h('div',{class:'row sp'},h('div',{class:'big',style:'font-size:26px'},`${ok} / ${tot} fields displayed`),h('span',{class:'chip '+(ok===tot?'pos':'neg')},ok===tot?'COMPLETE':'GAPS')),h('div',{class:'sub'},'Computed live from contracts.json (generated from the OpenAPI spec) vs. the fields each widget registered. /v3/public/* share their authed twin’s widgets.'),
    h('div',{class:'scroll',style:'max-height:420px;margin-top:8px'},h('table',{},h('thead',{},h('tr',{},['Endpoint','Field','Widget(s)'].map(x=>h('th',{},x)))),h('tbody',{},rows.flatMap(([k,its])=>its.map(([f,w],i)=>h('tr',{},h('td',{class:'mono dim'},i?'':k),h('td',{class:'mono'},f),h('td',{class:w?'cov-ok':'cov-miss'},w?[...new Set(w)].join(' '):'✗ missing')))))))))}

